steps.script:
for uid in GameState.state.units:
	var abs_ = GameState.state.units[uid].get("meta", {}).get("abilities", [])
	for i in range(abs_.size() - 1, -1, -1):
		var a = abs_[i]
		var n = str(a.get("name", "")) if a is Dictionary else str(a)
		if n.to_lower().begins_with("scout"):
			abs_.remove_at(i)
return GameState.get_scout_units_for_player(1).size() + GameState.get_scout_units_for_player(2).size()

var panel = tree.root.get_node_or_null("Main/GameLogPanel")
if panel == null:
	return "NO PANEL"
var stack = [panel]
var out = ""
while not stack.is_empty():
	var n = stack.pop_back()
	for c in n.get_children():
		stack.append(c)
	if n is RichTextLabel:
		out += n.get_parsed_text() + "\n"
	elif n is Label:
		out += str(n.text) + "\n"
return out.contains("No Scout moves are available")

